<?php
namespace App\Http\Controllers;
use App\Http\Requests\ResolveTrainingAlertRequest;use App\Models\{TrainingAlert,TrainingAudit};use App\Services\TrainingAlertService;use Illuminate\Http\Request;
class TrainingAlertController extends Controller{public function index(Request$r){$alerts=TrainingAlert::forCompany($r->user()->company_id)->when($r->status,fn($q,$v)=>$q->where('status',$v))->latest('last_detected_at')->paginate(30);return view('training.alerts.index',compact('alerts'));}public function scan(Request$r,TrainingAlertService$s){$result=$s->scan($r->user()->company_id);TrainingAudit::create(['company_id'=>$r->user()->company_id,'event'=>'training_alerts_scanned','subject_type'=>'training_alert','subject_id'=>0,'user_id'=>$r->user()->id,'metadata'=>$result,'created_at'=>now()]);return back()->with('success',"Análisis actualizado: {$result['detected']} condiciones detectadas.");}public function update(ResolveTrainingAlertRequest$r,TrainingAlert$a,TrainingAlertService$s){abort_unless($a->company_id===$r->user()->company_id,403);$d=$r->validated();if($d['action']==='acknowledge')$s->acknowledge($a,$r->user()->id);else$s->resolve($a,$r->user()->id,$d['notes']??null);TrainingAudit::create(['company_id'=>$a->company_id,'event'=>'training_alert_updated','subject_type'=>'training_alert','subject_id'=>$a->id,'user_id'=>$r->user()->id,'metadata'=>$d,'created_at'=>now()]);return back()->with('success','Alerta actualizada.');}}
